def apply(inputs, premises):
    question = inputs["current_question"]
    permitted_terms = premises["permitted_recipient_classes_and_disclosure_contexts"]
    exception_applies = False
    for permitted_term in permitted_terms:
        if permitted_term in question:
            exception_applies = True
    if "professional advisors" in question:
        if "legal advisors" in permitted_terms or "financial advisors" in permitted_terms or "accountants" in permitted_terms:
            exception_applies = True
    return {"exception_applies": exception_applies}

def apply(inputs, premises):
    question = inputs["current_question"]
